39: const intro=[
40:  {scene:"The old cherry path",pill:"Day 1 · 4:18 PM",speaker:"Narration",text:"The last petals of spring drift across the path behind Seiran University. You linger after class, pretending to check your phone, when a familiar voice calls your name.",char:null},
41:  {scene:"A familiar hello",pill:"Day 1 · 4:20 PM",speaker:"Akari",text:"There you are! I thought you might still be around. The light is so pretty today—I was going to walk down to the river. Want to come?",char:"akari"},
42:  {scene:"A second invitation",pill:"Day 1 · 4:21 PM",speaker:"Hana",text:"Akari, I found your sketchbook in the studio. Oh—hi. I was heading to the greenhouse to return these keys. Would you like to see the new seedlings with me?",char:"hana"},
43:  {scene:"Choose your afternoon",pill:"Day 1 · 4:22 PM",speaker:"Narration",text:"Two invitations, and enough afternoon for only one. You take a breath and decide where the day will lead.",char:null,options:[
44:    {label:"Walk with Akari by the river",hint:"A little sunshine and an old friend",route:"akari",reply:"Akari's whole face brightens. “Perfect! I know just the spot.” She falls into step beside you, humming a tune you almost recognize."},
45:    {label:"Visit the greenhouse with Hana",hint:"A quiet corner and a new beginning",route:"hana",reply:"Hana smiles, a little surprised. “I'd like that.” She holds the door for you, and the warm, green scent of the greenhouse welcomes you in."}
46:  ]}
47: ];
48: const routeStories={
49:  akari:[
50:   {scene:"The riverside",pill:"Day 1 · 4:39 PM",speaker:"Akari",text:"The river catches the evening sun in ribbons of gold. Akari sets her sketchbook on the bench, then pauses with her pencil in the air. “I keep drawing the same places. I want to make something that feels like being here, right now.”",char:"akari",options:[
51:    {label:"Ask her what this moment feels like",hint:"Listen before you offer advice",points:1,reply:"“Like the world finally exhaled,” she says. Her shoulders loosen. “That's it. Thank you for helping me find the words.”"},
52:    {label:"Suggest she draw the river's reflection",hint:"Give her an idea to play with",points:0,reply:"She tries a few strokes, then laughs. “The river won't sit still for me. Maybe that's the point.” She turns to a fresh page."}
53:   ]},
54:   {scene:"A small confession",pill:"Day 1 · 5:02 PM",speaker:"Akari",text:"She tells you about her dream of illustrating children's books—and how scary it feels to show anyone her work. A breeze flips open the sketchbook to a page of tiny, lively characters.",char:"akari",options:[
55:    {label:"Tell her you'd love to see more",hint:"Make room for her to share",points:1,reply:"Akari's smile goes shy around the edges. “Maybe I can show you the rest sometime. I think… I'd really like that.”"},
56:    {label:"Share something you're nervous about too",hint:"Meet her honesty with your own",points:1,reply:"You trade worries until they feel smaller. Akari listens as carefully as you did, and the river seems to slow around you."}
57:   ]},
58:   {scene:"Last train of sunlight",pill:"Day 1 · 5:31 PM",speaker:"Akari",text:"At the station gate, the sky has turned the soft pink of her pencil case. Akari fiddles with the strap of her bag. “Would you maybe want to do this again? No sketchbook required. Unless you want one.”",char:"akari",options:[
59:    {label:"“I'd like that. Let's make it our little tradition.”",hint:"Say what you mean",points:1,reply:"“Our little tradition,” she repeats, smiling. She walks home with her sketchbook tucked close and a new page already taking shape."},
60:    {label:"“Anytime. You can message me.”",hint:"Keep the door open",points:0,reply:"“I will!” Akari waves as the train pulls in. The goodbye feels less like an ending and more like a promise waiting for another day."}
61:   ]},
62:   {ending:true,route:"akari"}
63:  ],
64:  hana:[
65:   {scene:"The greenhouse",pill:"Day 1 · 4:39 PM",speaker:"Hana",text:"Inside the greenhouse, late sunlight turns every leaf translucent. Hana kneels beside a tray of seedlings. “These are moonflowers. They only bloom at night. Most people never see them.”",char:"hana",options:[
66:    {label:"Ask what she likes about growing things",hint:"Let her set the pace",points:1,reply:"“You can't hurry them,” she says, brushing soil from her fingertips. “You just make a little space, and trust they'll find their way.”"},
67:    {label:"Offer to help with the seedlings",hint:"Get your hands a little dirty",points:0,reply:"She shows you how to loosen the roots without hurting them. Your hands get muddy; Hana's laugh is bright and easy."}
68:   ]},
69:   {scene:"A quiet truth",pill:"Day 1 · 5:02 PM",speaker:"Hana",text:"As you water the seedlings, Hana admits she signed up to lead the campus garden project, then nearly backed out. “I like being useful. Being seen is harder.”",char:"hana",options:[
70:    {label:"Tell her it's okay to be nervous",hint:"Offer understanding, not a fix",points:1,reply:"Hana looks at you for a long moment. “I needed to hear that.” Her voice softens. “Maybe I can be nervous and still do it.”"},
71:    {label:"Offer to be there at her first meeting",hint:"Make the next step less lonely",points:1,reply:"“You'd do that?” She smiles, relief passing over her face. “I think I could walk in if I knew you'd be there.”"}
72:   ]},
73:   {scene:"The first moonflower",pill:"Day 1 · 5:31 PM",speaker:"Hana",text:"At the greenhouse door, one moonflower has unfurled, pale against the deepening sky. Hana looks from the bloom to you. “I don't usually invite people into my quiet places. I'm glad I did.”",char:"hana",options:[
74:    {label:"“I'd like to see this place with you again.”",hint:"Make a gentle promise",points:1,reply:"“Then I'll save you a place.” Hana's hand brushes yours, and neither of you rushes to pull away."},
75:    {label:"“Show me the garden project sometime?”",hint:"Keep growing this friendship",points:0,reply:"“I'd love to.” Her eyes brighten. “I'll show you the whole garden when it's in bloom.”"}
76:   ]},
77:   {ending:true,route:"hana"}
78:  ]
