/* Original urban-anime direction: bold cel accents, streetwear details and a neon-night interface. */
:root{--ink:#f4f3f5;--muted:#a5a9b5;--rose:#ff536f;--cream:#111722;--line:rgba(255,255,255,.1);--shadow:0 28px 90px rgba(0,0,0,.5)}
body{background:#0b1018;color:#f4f3f5;font-family:Inter,"Avenir Next",Avenir,"Segoe UI",sans-serif}
body:before{background:radial-gradient(ellipse at 9% 12%,#582547 0,transparent 32%),radial-gradient(ellipse at 92% 78%,#123c4b 0,transparent 30%),linear-gradient(135deg,#101521,#171421 60%,#0d1b25)}
.game{background:#111722;border:1px solid rgba(255,255,255,.12);border-radius:18px;box-shadow:0 28px 90px #0009}
.topbar{background:#111722;border-color:rgba(255,255,255,.1)}
.brand{color:#f7f5f8;letter-spacing:.17em}.brand-mark{background:#ff536f;color:#15121b;border-radius:8px;box-shadow:0 0 20px #ff536f66}
.chapter,.sound-btn,.restart-btn{color:#a5a9b5}.sound-btn:hover,.restart-btn:hover{color:#43d8e6}
.stage{background:#161c2b}
.scene-art{background:linear-gradient(180deg,#403052 0%,#a64c69 28%,#e67869 48%,#254151 78%,#101722 100%)}
.sun{background:#ffb36b;box-shadow:0 0 80px 30px #ff7b7366}
.cloud{background:rgba(255,198,193,.34)}
.distant{background:#463b58;opacity:.85;clip-path:polygon(0 70%,6% 70%,6% 37%,12% 37%,12% 57%,18% 57%,18% 18%,26% 18%,26% 69%,33% 69%,33% 42%,40% 42%,40% 11%,48% 11%,48% 68%,55% 68%,55% 34%,63% 34%,63% 62%,70% 62%,70% 22%,79% 22%,79% 69%,86% 69%,86% 39%,93% 39%,93% 58%,100% 58%,100% 100%,0 100%)}
.trees{opacity:.42;filter:hue-rotate(35deg)}
.ground{background:linear-gradient(170deg,#32424b,#101722)}
.path{background:linear-gradient(90deg,transparent,#f3a27755 48%,transparent);opacity:.9}
.fence{background:#ffb36b55;box-shadow:0 14px #ffb36b33,0 28px #ffb36b22}.fence:after{opacity:.6}
.petals{opacity:.42;filter:hue-rotate(160deg)}
.character{filter:drop-shadow(0 12px 18px #090a18aa) drop-shadow(0 0 16px #47d9e644);animation:character-arrive .42s cubic-bezier(.2,.8,.2,1) both}
.character.hidden{animation:none}
.char-svg{position:relative;z-index:1;overflow:visible}
.character:before{content:"";position:absolute;z-index:0;left:13%;right:13%;bottom:3%;height:62%;background:linear-gradient(145deg,#43d8e633,#ff536f22);clip-path:polygon(22% 0,78% 0,100% 100%,0 100%);filter:blur(20px)}
@keyframes character-arrive{from{opacity:0;transform:translate(-50%,16px) scale(.97)}to{opacity:1;transform:translate(-50%,0) scale(1)}}
.nameplate{background:#111722c9;border:1px solid #ffffff25;color:#f7f5f8;backdrop-filter:blur(10px)}
.chapter-pill{background:#121824b8;border:1px solid #ffffff20;color:#56e3eb}
.dialogue-wrap{background:linear-gradient(transparent,#10151ff5 32%)}
.dialogue{background:rgba(17,23,34,.97);border:1px solid #ffffff1b;border-radius:14px;box-shadow:0 16px 42px #05070bb3}
.speaker{color:#ff7184}.dialogue-text{color:#f2eff4}
.next{color:#4bdde5}.next:hover{color:#ff7184}
.choice{background:#171f2c;border-color:#374152;color:#f6f3f5}.choice span{color:#62dbe2}
.choice:hover,.choice:focus-visible{border-color:#ff657b;background:#24202e;box-shadow:0 7px 22px #ff536f22}
.progress{background:#222a36}.progress-fill{background:linear-gradient(90deg,#ff536f,#ffb36b,#43d8e6)}
.overlay{background:linear-gradient(145deg,#080d16bb,#171020d9);backdrop-filter:blur(8px)}
.title-card{background:#111722f5;border:1px solid #ffffff23;border-radius:18px;box-shadow:0 30px 90px #000b;text-align:left;position:relative;overflow:hidden}
.title-card:before{content:"";position:absolute;left:0;top:0;width:5px;height:100%;background:linear-gradient(#ff536f,#43d8e6)}
.eyebrow{color:#53dfe7}.title-card h1{font-family:Inter,"Avenir Next",sans-serif;font-weight:900;letter-spacing:-.06em;color:#f6f2f6;text-transform:uppercase}.title-card h1 em{font-style:normal;color:#ff657b}
.title-card p{color:#b4b1bd}.start-btn{background:#ff536f;color:#17111b;box-shadow:0 8px 22px #ff536f42}.start-btn:hover{background:#ff7587}
.tiny-note{color:#9295a3!important}.ending h2{color:#f7f2f5}.ending p{color:#b4b1bd}.secondary-btn{background:#171f2c;border-color:#404755;color:#60dce3}.secondary-btn:hover{background:#252b38}.sound-label{color:#a5a9b5}
